// Проверка текста запроса во внешнюю базу.
//
// Это второй рубеж, не единственный. Первый — роль в базе, которой выдан один
// лишь SELECT. Третий — read-only транзакция, в которой запрос выполняется.
// Одного рубежа мало: роль заводит человек и может выдать шире, чем задумано,
// а код может ошибиться. Это чужие боевые базы, и цена ошибки — не наши данные.
//
// Модель до этого слоя не достаёт: SQL пишется в коде, ей достаются именованные
// инструменты с типизированными параметрами.

export type ExternalEngine = 'postgres' | 'mysql';

/**
 * Слова, с которых начинается изменение данных.
 *
 * Проверено на живом PostgreSQL 16: «WITH x AS (INSERT … RETURNING id) SELECT id
 * FROM x» — это ОДИН оператор, он начинается со слова WITH, в нём нет точки с
 * запятой, и он действительно пишет в таблицу. Ради этого случая проверка и
 * существует; на «первое слово — SELECT» полагаться нельзя.
 *
 * В MySQL пишущих CTE нет, но список общий на оба движка: проверка бесплатна и
 * переживёт переезд базы с движка на движок.
 *
 * Слов вроде SET, COMMENT, COPY, LOCK здесь намеренно нет: без точки с запятой
 * они отдельным оператором не станут, а как имена колонок встречаются сплошь и
 * рядом — «comment» в базе маркетинга отвергался бы на ровном месте.
 */
const WRITING_WORDS = /\b(insert|update|delete|merge|truncate|drop|alter|create|grant|revoke)\b/i;

/**
 * Запись файла на сервере базы. Специфика MySQL, и самая коварная из всех:
 * «SELECT * FROM t INTO OUTFILE '/tmp/x'» начинается со слова SELECT, состоит из
 * одного оператора и не содержит ни одного слова из WRITING_WORDS — а пишет.
 */
const FILE_WRITE = /\binto\s+(outfile|dumpfile)\b/i;

/**
 * Блокировки. Это не запись, но это блокировки на чужой боевой базе: зависший
 * аналитический запрос способен остановить цех. Тамаре они не нужны нигде.
 */
const LOCKING = /\b(for\s+update|for\s+share|lock\s+in\s+share\s+mode)\b/i;

/** Убирает комментарии, строковые литералы и закавыченные имена. */
function stripNoise(query: string): string {
    return query
        .replace(/--[^\n]*/g, ' ')           // однострочные комментарии
        .replace(/#[^\n]*/g, ' ')            // однострочные по-мускульному
        .replace(/\/\*[\s\S]*?\*\//g, ' ')   // блочные
        .replace(/\$([A-Za-z_]\w*)?\$[\s\S]*?\$\1?\$/g, " '' ") // долларовые литералы Postgres
        .replace(/'(?:[^']|'')*'/g, " '' ")  // строковые литералы
        .replace(/"(?:[^"]|"")*"/g, ' _ ')   // закавыченные идентификаторы Postgres
        .replace(/`(?:[^`]|``)*`/g, ' _ ');  // закавыченные идентификаторы MySQL
}

/**
 * Запрос обязан быть одним SELECT (допускается ведущий WITH).
 *
 * Движок влияет на набор запретов, но не на строгость: то, что запрещено одному,
 * запрещено и другому. Разделение нужно лишь для внятного сообщения об ошибке.
 */
export function assertReadOnlyQuery(query: string, engine: ExternalEngine = 'postgres'): void {
    const stripped = stripNoise(query).trim();

    if (!stripped) throw new Error('Пустой запрос');

    // Точка с запятой внутри текста запроса — почти всегда попытка приписать
    // второй оператор. Хвостовую отбрасываем, любую другую считаем ошибкой.
    const body = stripped.replace(/;\s*$/, '');
    if (body.includes(';')) throw new Error('Во внешнюю базу разрешён только один оператор');

    if (!/^(select|with)\b/i.test(body)) {
        throw new Error('Во внешнюю базу разрешён только SELECT');
    }

    // Блокировки проверяются ПЕРВЫМИ: «FOR UPDATE» иначе поймается по слову
    // UPDATE и объяснит человеку не то, что произошло на самом деле.
    const lock = body.match(LOCKING);
    if (lock) {
        throw new Error(
            `Блокировки во внешней базе запрещены: ${lock[1].replace(/\s+/g, ' ').toUpperCase()}. ` +
                'Это чужая боевая база, зависший запрос остановит работу.',
        );
    }

    const file = body.match(FILE_WRITE);
    if (file) {
        throw new Error(
            `Запись файла на сервере базы запрещена: INTO ${file[1].toUpperCase()}` +
                (engine === 'mysql' ? '' : ' (проверка общая на оба движка)'),
        );
    }

    const writing = body.match(WRITING_WORDS);
    if (writing) {
        throw new Error(`Во внешнюю базу разрешён только SELECT, найдено: ${writing[1].toUpperCase()}`);
    }
}
